// B+树结点结构
const int M = 100;  // 每个结点最多M-1个关键字

typedef struct BPlusNode {
    int keynum;                       // 当前关键字数
    int keys[M];                      // 关键字数组 [1..keynum]
    struct BPlusNode* children[M+1];  // 子树指针 [0..keynum]
    struct BPlusNode* next;           // 叶子结点的后继链表指针
    bool isLeaf;                      // 是否叶子结点
} BPlusNode;

// B+树的查找 (返回关键字所在叶子结点及索引)
bool BPlusSearch(BPlusNode* root, int key, BPlusNode*& leaf, int& idx) {
    BPlusNode* p = root;
    while (!p->isLeaf) {  // 沿分支向下直到叶子
        // 在非叶结点中查找key应属于哪个子树
        idx = 1;
        while (idx <= p->keynum && p->keys[idx] < key) idx++;
        // idx是第一个 >= key 的位置, 进入子树p->children[idx-1]或p->children[idx]
        // (具体取决于B+树的分支策略)
        p = p->children[idx - 1];
    }
    // 到达叶子结点, 在叶子内顺序查找
    leaf = p;
    for (idx = 1; idx <= leaf->keynum; idx++)
        if (leaf->keys[idx] == key) return true;
    return false;
}

