// B+树的范围查询: 从key1开始顺序访问到key2
void BPlusRangeQuery(BPlusNode* root, int key1, int key2) {
    BPlusNode* leaf; int idx;
    BPlusSearch(root, key1, leaf, idx);  // 找到起始位置所在叶子
    // 从该位置开始, 沿next指针顺序访问
    while (leaf) {
        for (int i = idx; i <= leaf->keynum && leaf->keys[i] <= key2; i++)
            cout << leaf->keys[i] << " ";
        leaf = leaf->next;
        idx = 1;
    }
}

// B+树特点:
// 1. 所有关键字都在叶子结点 (非叶结点是"分界")
// 2. 叶子结点顺序链接成链表, 支持顺序遍历和范围查询
// 3. 树高约为 log_{M/2}(n), 通常 M=100~1000, 树高仅3~4层
// 4. 每次查询/插入/删除只需约 h 次I/O (h为树高, 3~4次)
// 5. 是数据库索引的主要实现方式 (MySQL InnoDB, SQL Server等)

// 倒排索引 (Inverted Index)
// 应用: 搜索引擎、信息检索
// 思路: 从"文档->关键词" 反转为 "关键词->文档列表"

#include <map>
#include <vector>
#include <string>
using namespace std;

// 倒排列表: 每个关键词对应哪些文档 (及位置信息)
typedef struct Posting {
    int docID;       // 文档ID
    int freq;        // 词频
    vector<int> pos; // 词在文档中的位置
} Posting;

map<string, vector<Posting>> invertedIndex;  // 倒排索引
map<int, string> docTable;                   // 文档表 (docID -> 文档内容)

// 建立倒排索引: 遍历每个文档, 对每个词将(docID, 位置)加入倒排列表
void buildIndex(int docID, string content) {
    docTable[docID] = content;
    // 分词, 统计词频和位置
    map<string, pair<int, vector<int>>> wordInfo;
    // ... 分词处理
    for (auto& kv : wordInfo) {
        Posting p;
        p.docID = docID;
        p.freq = kv.second.first;
        p.pos = kv.second.second;
        invertedIndex[kv.first].push_back(p);
    }
}

// 布尔查询: "A AND B" = 两个词的倒排列表求交集
vector<int> queryAND(string wordA, string wordB) {
    vector<int> result;
    auto& listA = invertedIndex[wordA];
    auto& listB = invertedIndex[wordB];
    // 双指针法求交集 (docID有序)
    int i = 0, j = 0;
    while (i < listA.size() && j < listB.size()) {
        if (listA[i].docID == listB[j].docID) {
            result.push_back(listA[i].docID);
            i++; j++;
        } else if (listA[i].docID < listB[j].docID) i++;
        else j++;
    }
    return result;
}

